1	/****************************************************************************
2	 * Contest 2026 team 181 - AI Agent App with LVGL Display
3	 *
4	 * AI agent with AMOLED display support for SF32LB52-DevKit-LCD.
5	 * Displays "你好HerSen" on startup and shows AI responses on screen.
6	 ****************************************************************************/
7	
8	#include <nuttx/config.h>
9	#include <stdio.h>
10	#include <stdlib.h>
11	#include <string.h>
12	#include <unistd.h>
13	
14	/* LVGL headers */
15	
16	#include <lvgl/lvgl.h>
17	#include <lvgl/src/drivers/nuttx/lv_nuttx_entry.h>
18	
19	/****************************************************************************
20	 * Pre-processor Definitions
21	 ****************************************************************************/
22	
23	#define AI_AGENT_MAX_INPUT_LEN    256
24	#define AI_AGENT_PROMPT           "ai> "
25	#define AI_AGENT_TITLE            "你好HerSen"
26	
27	/****************************************************************************
28	 * Private Data
29	 ****************************************************************************/
30	
31	static lv_obj_t *g_title_label = NULL;    /* Title label */
32	static lv_obj_t *g_response_label = NULL; /* Response label */
33	static lv_obj_t *g_status_label = NULL;   /* Status label */
34	
35	/****************************************************************************
36	 * Simulated AI Responses
37	 ****************************************************************************/
38	
39	typedef struct
40	{
41	  const char *keyword;
42	  const char *response;
43	} ai_response_t;
44	
45	static const ai_response_t g_responses[] =
46	{
47	  {"hello",    "你好! I'm your AI assistant on SF32LB52. 有什么可以邦到您？"},
48	  {"nuttx",    "NuttX is a real-time operating system (RTOS) with a small footprint. It's POSIX-compatible and great for IoT devices!"},
49	  {"vela",     "OpenVela is Xiaomi's open-source IoT platform based on NuttX. It supports many hardware platforms including the SF32LB52!"},
50	  {"sifli",    "SiFli makes the SF32LB52 chip - a powerful ARM Cortex-M33 MCU with BLE, WiFi, and display support."},
51	  {"weather",  "I'm running on a development board without sensors, so I can't check the weather. But you could connect a sensor!"},
52	  {"help",     "Available commands:\n  - Ask any question\n  - Type 'quit' to exit\n  - Try keywords: nuttx, vela, sifli, hello"},
53	  {"lcd",      "The SF32LB52-DevKit-LCD has a 1.85 inch 390x450 CO5300 AMOLED display with capacitive touch!"},
54	  {"default",  "That's an interesting question! I'm a simple AI agent running on embedded hardware. For full AI capabilities, connect to the cloud."},
55	};
56	
57	#define NUM_RESPONSES (sizeof(g_responses) / sizeof(g_responses[0]))
58	
59	/****************************************************************************
60	 * LVGL Display Functions
61	 ****************************************************************************/
62	
63	/****************************************************************************
64	 * Name: display_init
65	 *
66	 * Description:
67	 *   Initialize LVGL and create the display layout.
68	 *
69	 ****************************************************************************/
70	
71	static int display_init(void)
72	{
73	  lv_nuttx_result_t result;
74	  lv_nuttx_dsc_t info;
75	
76	  printf("Initializing LVGL display...\n");
77	
78	  /* Initialize LVGL */
79	
80	  lv_init();
81	
82	  /* Initialize NuttX display driver */
83	
84	  lv_nuttx_dsc_init(&info);
85	  info.fb_path = "/dev/lcd0";
86	  info.input_path = "/dev/input0";
87	
88	  lv_nuttx_init(&info, &result);
89	
90	  if (result.disp == NULL)
91	    {
92	      printf("ERROR: Failed to initialize LVGL NuttX driver\n");
93	      return -1;
94	    }
95	
96	  /* Create black background */
97	
98	  lv_obj_t *scr = lv_screen_active();
99	  lv_obj_set_style_bg_color(scr, lv_color_black(), 0);
100	
101	  /* Create title label - "你好HerSen" */
102	
103	  g_title_label = lv_label_create(scr);
104	  lv_label_set_text(g_title_label, AI_AGENT_TITLE);
105	  lv_obj_set_style_text_color(g_title_label, lv_color_make(0, 255, 0), 0);
106	  lv_obj_set_style_text_font(g_title_label, &lv_font_simsun_16_cjk, 0);
107	  lv_obj_align(g_title_label, LV_ALIGN_TOP_MID, 0, 20);
108	
109	  /* Create status label */
110	
111	  g_status_label = lv_label_create(scr);
112	  lv_label_set_text(g_status_label, "AI Agent Ready");
113	  lv_obj_set_style_text_color(g_status_label, lv_color_make(200, 200, 200), 0);
114	  lv_obj_set_style_text_font(g_status_label, &lv_font_simsun_16_cjk, 0);
115	  lv_obj_align(g_status_label, LV_ALIGN_TOP_MID, 0, 50);
116	
117	  /* Create response label - for AI responses */
118	
119	  g_response_label = lv_label_create(scr);
120	  lv_label_set_text(g_response_label, "Waiting for query...");
121	  lv_obj_set_style_text_color(g_response_label, lv_color_white(), 0);
122	  lv_obj_set_style_text_font(g_response_label, &lv_font_simsun_16_cjk, 0);
123	  lv_obj_set_width(g_response_label, 370);
124	  lv_label_set_long_mode(g_response_label, LV_LABEL_LONG_WRAP);
125	  lv_obj_align(g_response_label, LV_ALIGN_TOP_LEFT, 10, 90);
126	
127	  /* Run one round of lv_timer_handler to refresh display */
128	
129	  lv_timer_handler();
130	
131	  printf("Display initialized successfully!\n");
132	  return 0;
133	}
134	
135	/****************************************************************************
136	 * Name: display_update_response
137	 *
138	 * Description:
139	 *   Update the response label with new text.
140	 *
141	 ****************************************************************************/
142	
143	static void display_update_response(const char *text)
144	{
145	  if (g_response_label != NULL)
146	    {
147	      lv_label_set_text(g_response_label, text);
148	      lv_timer_handler();
149	    }
150	}
151	
152	/****************************************************************************
153	 * Name: display_update_status
154	 *
155	 * Description:
156	 *   Update the status label.
157	 *
158	 ****************************************************************************/
159	
160	static void display_update_status(const char *status)
161	{
162	  if (g_status_label != NULL)
163	    {
164	      lv_label_set_text(g_status_label, status);
165	      lv_timer_handler();
166	    }
167	}
168	
169	/****************************************************************************
170	 * AI Agent Functions
171	 ****************************************************************************/
172	
173	static void ai_agent_show_usage(void)
174	{
175	  printf("Usage: ai_agent [options]\n"
176	         "  -h          : show this help\n"
177	         "  -q <query>  : send a query\n"
178	         "  -n          : no display (skip LVGL init)\n"
179	         "  -i          : interactive mode (default)\n");
180	}
181	
182	static const char *ai_agent_find_response(const char *query)
183	{
184	  int i;
185	  char lower_query[AI_AGENT_MAX_INPUT_LEN];
186	
187	  /* Convert query to lowercase for matching */
188	
189	  strncpy(lower_query, query, sizeof(lower_query) - 1);
190	  lower_query[sizeof(lower_query) - 1] = '\0';
191	
192	  for (i = 0; lower_query[i]; i++)
193	    {
194	      if (lower_query[i] >= 'A' && lower_query[i] <= 'Z')
195	        {
196	          lower_query[i] = lower_query[i] + 32;
197	        }
198	    }
199	
200	  /* Search for keyword match */
201	
202	  for (i = 0; i < NUM_RESPONSES - 1; i++)
203	    {
204	      if (strstr(lower_query, g_responses[i].keyword) != NULL)
205	        {
206	          return g_responses[i].response;
207	        }
208	    }
209	
210	  /* Return default response */
211	
212	  return g_responses[NUM_RESPONSES - 1].response;
213	}
214	
215	static int ai_agent_query(const char *query)
216	{
217	  const char *response;
218	
219	  printf("Thinking...\n");
220	  display_update_status("Thinking...");
221	
222	  /* Simulate processing time */
223	
224	  usleep(500000);  /* 0.5 second */
225	
226	  /* Find response */
227	
228	  response = ai_agent_find_response(query);
229	
230	  /* Display on screen */
231	
232	  display_update_response(response);
233	  display_update_status("AI Agent Ready");
234	
235	  /* Also print to console */
236	
237	  printf("\n--- AI Response ---\n");
238	  printf("%s\n", response);
239	  printf("--- End ---\n\n");
240	
241	  return 0;
242	}
243	
244	static int ai_agent_interactive(void)
245	{
246	  char input[AI_AGENT_MAX_INPUT_LEN];
247	
248	  printf("\n=== AI Agent Interactive Mode ===\n");
249	  printf("Type your questions or 'quit' to exit.\n");
250	  printf("Try: hello, nuttx, vela, sifli, lcd, help\n\n");
251	
252	  display_update_status("Interactive Mode - Type on console");
253	
254	  while (1)
255	    {
256	      printf("%s", AI_AGENT_PROMPT);
257	      fflush(stdout);
258	
259	      /* Run LVGL while waiting for input */
260	
261	      lv_timer_handler();
262	
263	      /* Read input */
264	
265	      if (fgets(input, sizeof(input), stdin) == NULL)
266	        {
267	          break;
268	        }
269	
270	      /* Remove newline */
271	
272	      input[strcspn(input, "\n")] = '\0';
273	
274	      /* Check for exit command */
275	
276	      if (strcmp(input, "quit") == 0 || strcmp(input, "exit") == 0)
277	        {
278	          printf("Goodbye!\n");
279	          display_update_status("Goodbye!");
280	          break;
281	        }
282	
283	      /* Skip empty input */
284	
285	      if (strlen(input) == 0)
286	        {
287	          continue;
288	        }
289	
290	      /* Process the query */
291	
292	      ai_agent_query(input);
293	    }
294	
295	  return 0;
296	}
297	
298	/****************************************************************************
299	 * Public Functions
300	 ****************************************************************************/
301	
302	/****************************************************************************
303	 * Name: ai_agent_main
304	 *
305	 * Description:
306	 *   AI Agent application entry point.
307	 *
308	 ****************************************************************************/
309	
310	int main(int argc, char *argv[])
311	{
312	  int ret = 0;
313	  int opt;
314	  const char *query = NULL;
315	  bool no_display = false;
316	
317	  /* Parse command line arguments */
318	
319	  while ((opt = getopt(argc, argv, "hq:n")) != -1)
320	    {
321	      switch (opt)
322	        {
323	          case 'h':
324	            ai_agent_show_usage();
325	            return EXIT_SUCCESS;
326	
327	          case 'q':
328	            query = optarg;
329	            break;
330	
331	          case 'n':
332	            no_display = true;
333	            break;
334	
335	          default:
336	            ai_agent_show_usage();
337	            return EXIT_FAILURE;
338	        }
339	    }
340	
341	  printf("========================================\n");
342	  printf("  AI Agent v2.0 - SF32LB52-DevKit-LCD\n");
343	  printf("  Contest 2026 Team 181\n");
344	  printf("  With AMOLED Display Support\n");
345	  printf("========================================\n\n");
346	
347	  /* Initialize display (unless -n is specified) */
348	
349	  if (!no_display)
350	    {
351	      ret = display_init();
352	      if (ret != 0)
353	        {
354	          printf("WARNING: Display init failed, continuing with console only\n");
355	        }
356	    }
357	  else
358	    {
359	      printf("Display skipped (console only mode)\n");
360	    }
361	
362	  /* Process based on mode */
363	
364	  if (query != NULL)
365	    {
366	      /* Single query mode */
367	
368	      ret = ai_agent_query(query);
369	      usleep(3000000);  /* Wait 3 seconds to show result */
370	    }
371	  else
372	    {
373	      /* Default: enter interactive mode */
374	
375	      ret = ai_agent_interactive();
376	    }
377	
378	  return (ret == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
379	}
