    lv_anim_set_playback_time(&pet_blink_anim, 100);
    lv_anim_set_repeat_delay(&pet_blink_anim, 2800);
    lv_anim_set_repeat_count(&pet_blink_anim, LV_ANIM_REPEAT_INFINITE);
    lv_anim_start(&pet_blink_anim);
}

